shell_commands:
node --input-type=module -e "
import ajv8 from './node_modules/ajv/dist/ajv.js';
import ajv6 from './node_modules/eslint/node_modules/ajv/lib/ajv.js';
console.log('ajv8:', typeof ajv8, typeof new (ajv8.default ?? ajv8)({strict: false, validateFormats: false, allErrors: true}));
console.log('ajv6:', typeof ajv6, typeof new (ajv6.default ?? ajv6)({strict: false, validateFormats: false, allErrors: true}));
"

node --input-type=module -e "
import ajv8 from './node_modules/ajv/dist/ajv.js';
import ajv6 from './node_modules/eslint/node_modules/ajv/lib/ajv.js';

const schema = {
  type: 'object',
  properties: {
    location: {type: 'string'},
    unit: {type: 'string', enum: ['celsius', 'fahrenheit']},
    nested: {type: 'object', properties: {code: {type: 'number'}}, required: ['code']}
  },
  required: ['location']
};

for (const [label, Mod] of [['ajv8', ajv8.default ?? ajv8], ['ajv6', ajv6.default ?? ajv6]]) {
  const instance = new Mod({strict: false, validateFormats: false, allErrors: true});
  const validate = instance.compile(schema);
  validate({location: 123456789, unit: 'kelvin', nested: {code: 'secret-val'}});
  console.log(label, validate.errors);
}
"

node --input-type=module -e "
import {readFileSync, writeFileSync} from 'node:fs';
import {format, resolveConfig} from 'prettier';
for (const f of ['src/orchestration/tools/registry.ts', 'src/orchestration/tools/registry.acceptance.test.ts', 'src/orchestration/tools/registry.test.ts']) {
  const cfg = await resolveConfig(f);
  const src = readFileSync(f, 'utf8');
  const formatted = await format(src, {...cfg, filepath: f});
  if (src !== formatted) {
    writeFileSync(f, formatted);
    console.log('formatted:', f);
  } else {
    console.log('clean:', f);
  }
}
"
